import"./chunk-VC46IEJQ.js";var a=(r,o,n,s={})=>({id:r,name:{en:o,zh:n},...s}),e=(r,o)=>({en:r,zh:o}),t={group:"crownlands",houses:[{id:"targaryen",names:e("House Targaryen","\u5766\u683C\u5229\u5B89\u5BB6\u65CF"),region:"crownlands",seat:"kings-landing",otherSeats:["dragonstone"],tier:"great",liege:null,sigil:e("A red three-headed dragon on a black field","\u9ED1\u5E95\u4E0A\u4E00\u6761\u4E09\u5934\u7EA2\u9F99"),colors:["#141414","#b0221d"],words:e("Fire and Blood","\u8840\u706B\u540C\u6E90"),summary:e("Dragonlords of Old Valyria who settled on Dragonstone before the Doom and, under Aegon the Conqueror, united six of the Seven Kingdoms by dragonfire. They ruled from the Iron Throne for nearly three centuries until Robert's Rebellion overthrew Aerys II, the Mad King. In the books the surviving heirs, Viserys and Daenerys, live in exile across the Narrow Sea.","\u53E4\u74E6\u96F7\u5229\u4E9A\u7684\u9F99\u738B\u540E\u88D4\uFF0C\u5728\u672B\u65E5\u6D69\u52AB\u4E4B\u524D\u5B9A\u5C45\u9F99\u77F3\u5C9B\uFF1B\u5F81\u670D\u8005\u4F0A\u803F\u51ED\u9F99\u7130\u7EDF\u4E00\u4E86\u4E03\u56FD\u4E2D\u7684\u516D\u56FD\u3002\u5BB6\u65CF\u5750\u62E5\u94C1\u738B\u5EA7\u8FD1\u4E09\u767E\u5E74\uFF0C\u76F4\u5230\u52B3\u52C3\u8D77\u4E49\u63A8\u7FFB\u201C\u75AF\u738B\u201D\u4F0A\u91CC\u65AF\u4E8C\u4E16\u3002\u5C0F\u8BF4\u5F00\u7BC7\u65F6\uFF0C\u5E78\u5B58\u7684\u7EE7\u627F\u4EBA\u97E6\u8D5B\u91CC\u65AF\u4E0E\u4E39\u59AE\u8389\u4E1D\u6D41\u4EA1\u4E8E\u72ED\u6D77\u5BF9\u5CB8\u3002"),refs:["agot","twoiaf"],members:[a("aegon-i-targaryen","Aegon I","\u4F0A\u803F\u4E00\u4E16",{spouses:["visenya-targaryen","rhaenys-targaryen-conquest"],note:e("Aegon the Conqueror, first king of the Seven Kingdoms.","\u5F81\u670D\u8005\u4F0A\u803F\uFF0C\u4E03\u5927\u738B\u56FD\u7684\u7B2C\u4E00\u4F4D\u56FD\u738B\u3002")}),a("visenya-targaryen","Visenya","\u7EF4\u6851\u5C3C\u4E9A",{note:e("Aegon's elder sister-wife, a warrior who bore the sword Dark Sister.","\u4F0A\u803F\u7684\u59D0\u59D0\u517C\u59BB\u5B50\uFF0C\u6301\u201C\u9ED1\u59D0\u59B9\u201D\u5251\u7684\u5973\u6218\u58EB\u3002")}),a("rhaenys-targaryen-conquest","Queen Rhaenys","\u96F7\u59AE\u4E1D\u738B\u540E",{note:e("Aegon's younger sister-wife, rider of Meraxes.","\u4F0A\u803F\u7684\u59B9\u59B9\u517C\u59BB\u5B50\uFF0C\u5DE8\u9F99\u7C73\u62C9\u897F\u65AF\u7684\u9A91\u624B\u3002")}),a("aenys-i-targaryen","Aenys I","\u4F0A\u5C3C\u65AF\u4E00\u4E16",{father:"aegon-i-targaryen",mother:"rhaenys-targaryen-conquest",note:e("Second king, son of Rhaenys.","\u7B2C\u4E8C\u4F4D\u56FD\u738B\uFF0C\u96F7\u59AE\u4E1D\u4E4B\u5B50\u3002")}),a("maegor-i-targaryen","Maegor I","\u6885\u845B\u4E00\u4E16",{father:"aegon-i-targaryen",mother:"visenya-targaryen",note:e("Maegor the Cruel, son of Visenya.","\u6B8B\u9177\u7684\u6885\u845B\uFF0C\u7EF4\u6851\u5C3C\u4E9A\u4E4B\u5B50\u3002")}),a("maekar-targaryen","Maekar I","\u6885\u5361\u4E00\u4E16",{note:e("King, fourth son of Daeron II; died fighting rebels.","\u56FD\u738B\uFF0C\u6234\u4F26\u4E8C\u4E16\u7B2C\u56DB\u5B50\uFF0C\u5728\u5E73\u53DB\u4E2D\u9635\u4EA1\u3002")}),a("daeron-targaryen-son-of-maekar","Daeron","\u6234\u4F26",{father:"maekar-targaryen",note:e("Maekar's eldest son, called the Drunken.","\u6885\u5361\u957F\u5B50\uFF0C\u4EBA\u79F0\u201C\u9189\u9B3C\u201D\u3002")}),a("aerion-targaryen","Aerion","\u4F0A\u5229\u6602",{father:"maekar-targaryen",note:e('"Brightfire"; died drinking wildfire.',"\u201C\u5149\u660E\u4E4B\u706B\u201D\uFF0C\u996E\u91CE\u706B\u800C\u6B7B\u3002")}),a("aemon-targaryen","Maester Aemon","\u4F0A\u8499\u5B66\u58EB",{father:"maekar-targaryen",note:e("Refused the crown; maester at Castle Black.","\u62D2\u7EDD\u738B\u51A0\uFF0C\u5728\u9ED1\u57CE\u5821\u62C5\u4EFB\u5B66\u58EB\u3002"),fate:e("Dies at sea on the voyage to Oldtown (A Feast for Crows).","\u5728\u524D\u5F80\u65E7\u9547\u7684\u822A\u7A0B\u4E2D\u6B7B\u4E8E\u6D77\u4E0A\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\u3002")}),a("aegon-v-targaryen","Aegon V","\u4F0A\u803F\u4E94\u4E16",{father:"maekar-targaryen",note:e('"The Unlikely"; died in the fire at Summerhall.',"\u201C\u610F\u5916\u4E4B\u738B\u201D\uFF0C\u6B7B\u4E8E\u76DB\u590F\u5385\u5927\u706B\u3002")}),a("duncan-targaryen","Duncan","\u9093\u80AF",{father:"aegon-v-targaryen",note:e('"The Small"; gave up the crown for love; died at Summerhall.',"\u201C\u5C0F\u738B\u5B50\u201D\uFF0C\u4E3A\u7231\u653E\u5F03\u738B\u4F4D\uFF0C\u6B7B\u4E8E\u76DB\u590F\u5385\u3002")}),a("jaehaerys-ii-targaryen","Jaehaerys II","\u6770\u8D6B\u91CC\u65AF\u4E8C\u4E16",{father:"aegon-v-targaryen",spouses:["shaera-targaryen"],note:e("Short-reigned king; wed his sister.","\u5728\u4F4D\u77ED\u6682\u7684\u56FD\u738B\uFF0C\u5A36\u4E86\u81EA\u5DF1\u7684\u59B9\u59B9\u3002")}),a("shaera-targaryen","Shaera","\u590F\u62C9",{father:"aegon-v-targaryen",note:e("Queen of Jaehaerys II.","\u6770\u8D6B\u91CC\u65AF\u4E8C\u4E16\u7684\u738B\u540E\u3002")}),a("rhaelle-targaryen","Rhaelle","\u857E\u5C14",{father:"aegon-v-targaryen",note:e("Wed Ormund Baratheon; mother of Steffon.","\u5AC1\u7ED9\u5965\u8499\u5FB7\xB7\u62DC\u62C9\u5E2D\u6069\uFF0C\u53F2\u8482\u82AC\u4E4B\u6BCD\u3002")}),a("aerys-ii-targaryen","Aerys II","\u4F0A\u91CC\u65AF\u4E8C\u4E16",{father:"jaehaerys-ii-targaryen",mother:"shaera-targaryen",spouses:["rhaella-targaryen"],note:e("The Mad King; slain by Jaime Lannister in the Sack.","\u75AF\u738B\uFF0C\u5728\u541B\u4E34\u9677\u843D\u65F6\u88AB\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u6240\u6740\u3002")}),a("rhaella-targaryen","Rhaella","\u857E\u62C9",{father:"jaehaerys-ii-targaryen",mother:"shaera-targaryen",note:e("Queen; died bearing Daenerys on Dragonstone.","\u738B\u540E\uFF0C\u5728\u9F99\u77F3\u5C9B\u751F\u4E0B\u4E39\u59AE\u8389\u4E1D\u65F6\u53BB\u4E16\u3002")}),a("rhaegar-targaryen","Rhaegar","\u96F7\u52A0",{father:"aerys-ii-targaryen",mother:"rhaella-targaryen",spouses:["elia-martell"],note:e("Prince of Dragonstone; slain by Robert at the Trident.","\u9F99\u77F3\u5C9B\u4EB2\u738B\uFF0C\u5728\u4E09\u53C9\u621F\u6CB3\u88AB\u52B3\u52C3\u6240\u6740\u3002")}),a("viserys-targaryen","Viserys","\u97E6\u8D5B\u91CC\u65AF",{father:"aerys-ii-targaryen",mother:"rhaella-targaryen",note:e('Exiled heir, "the Beggar King".',"\u6D41\u4EA1\u7684\u7EE7\u627F\u4EBA\uFF0C\u4EBA\u79F0\u201C\u4E5E\u4E10\u738B\u201D\u3002"),fate:e('Killed by Khal Drogo with a "crown" of molten gold (A Game of Thrones).',"\u88AB\u5353\u6208\u5361\u5965\u4EE5\u7194\u91D1\u201C\u52A0\u5195\u201D\u800C\u6B7B\uFF08\u300A\u6743\u529B\u7684\u6E38\u620F\u300B\uFF09\u3002")}),a("daenerys-targaryen","Daenerys","\u4E39\u59AE\u8389\u4E1D",{father:"aerys-ii-targaryen",mother:"rhaella-targaryen",note:e("Stormborn; last child of Aerys, raised in exile.","\u98CE\u66B4\u964D\u751F\uFF0C\u4F0A\u91CC\u65AF\u7684\u5E7A\u5973\uFF0C\u5728\u6D41\u4EA1\u4E2D\u957F\u5927\u3002"),fate:e("Hatches three dragons, frees Slaver's Bay and rules Meereen; at the end of A Dance with Dragons she is alone on the Dothraki sea with Drogon.","\u5B75\u5316\u4E09\u6761\u9F99\uFF0C\u89E3\u653E\u5974\u96B6\u6E7E\u5E76\u7EDF\u6CBB\u5F25\u6797\uFF1B\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u7ED3\u5C3E\u65F6\uFF0C\u5979\u4E0E\u5353\u803F\u72EC\u5904\u4E8E\u591A\u65AF\u62C9\u514B\u6D77\u3002")}),a("rhaenys-targaryen","Rhaenys","\u96F7\u59AE\u4E1D",{father:"rhaegar-targaryen",mother:"elia-martell",note:e("Rhaegar's daughter; killed in the Sack of King's Landing.","\u96F7\u52A0\u4E4B\u5973\uFF0C\u6B7B\u4E8E\u541B\u4E34\u9677\u843D\u3002")}),a("aegon-targaryen-son-of-rhaegar","Aegon","\u4F0A\u803F",{father:"rhaegar-targaryen",mother:"elia-martell",note:e("Rhaegar's infant son; said to have died in the Sack.","\u96F7\u52A0\u7684\u5E7C\u5B50\uFF0C\u636E\u8BF4\u6B7B\u4E8E\u541B\u4E34\u9677\u843D\u3002"),fate:e('In A Dance with Dragons a youth raised as "Young Griff" is presented as this Aegon, smuggled away before the Sack; whether the claim is true is left open.',"\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u4E00\u540D\u5316\u540D\u201C\u5C0F\u683C\u91CC\u592B\u201D\u957F\u5927\u7684\u5C11\u5E74\u88AB\u5BA3\u79F0\u5C31\u662F\u8FD9\u4F4D\u4F0A\u803F\uFF0C\u5728\u541B\u4E34\u9677\u843D\u524D\u88AB\u5077\u5077\u9001\u8D70\uFF1B\u6B64\u8BF4\u771F\u4F2A\u4E66\u4E2D\u672A\u6709\u5B9A\u8BBA\u3002")})]},{id:"velaryon",names:e("House Velaryon","\u74E6\u5217\u5229\u5B89\u5BB6\u65CF"),region:"crownlands",seat:"high-tide",otherSeats:["castle-driftmark"],tier:"major",liege:null,sigil:e("A silver seahorse on sea-green","\u6D77\u7EFF\u5E95\u4E0A\u4E00\u5339\u94F6\u8272\u6D77\u9A6C"),colors:["#2f7a6e","#d4d7db"],words:e("The Old, the True, the Brave","\u53E4\u8001\u3001\u5FE0\u8BDA\u3001\u52C7\u6562"),summary:e('An old house of Valyrian blood that came to Driftmark before the Targaryens and long commanded the royal fleet. Their wealth peaked under Corlys "the Sea Snake", whose voyages made them richer than the Lannisters for a time. In the books they follow Stannis, and Lord Monford dies at the Blackwater.',"\u4E00\u4E2A\u62E5\u6709\u74E6\u96F7\u5229\u4E9A\u8840\u7EDF\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u65E9\u4E8E\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u6765\u5230\u6F6E\u5934\u5C9B\uFF0C\u957F\u671F\u7EDF\u9886\u738B\u5BB6\u8230\u961F\u3002\u5BB6\u65CF\u8D22\u5BCC\u5728\u201C\u6D77\u86C7\u201D\u79D1\u5229\u65AF\u6CBB\u4E0B\u8FBE\u5230\u9876\u5CF0\uFF0C\u4ED6\u7684\u8FDC\u822A\u4E00\u5EA6\u4F7F\u5BB6\u65CF\u6BD4\u5170\u5C3C\u65AF\u7279\u66F4\u5BCC\u3002\u5C0F\u8BF4\u4E2D\u5BB6\u65CF\u8FFD\u968F\u53F2\u5766\u5C3C\u65AF\uFF0C\u8499\u798F\u5FB7\u4F2F\u7235\u6B7B\u4E8E\u9ED1\u6C34\u6CB3\u4E4B\u5F79\u3002"),refs:["acok","affc","twoiaf"],members:[a("corlys-velaryon","Corlys Velaryon","\u79D1\u5229\u65AF\xB7\u74E6\u5217\u5229\u5B89",{note:e('"The Sea Snake"; nine great voyages; built High Tide. Wed Princess Rhaenys.',"\u201C\u6D77\u86C7\u201D\uFF0C\u4E5D\u6B21\u8FDC\u822A\uFF0C\u5EFA\u9020\u6EE1\u6F6E\u5821\uFF1B\u5A36\u96F7\u59AE\u4E1D\u516C\u4E3B\u3002")}),a("laenor-velaryon","Laenor Velaryon","\u83B1\u8BFA\xB7\u74E6\u5217\u5229\u5B89",{father:"corlys-velaryon",note:e("First husband of Princess Rhaenyra.","\u96F7\u59AE\u62C9\u516C\u4E3B\u7684\u7B2C\u4E00\u4EFB\u4E08\u592B\u3002")}),a("laena-velaryon","Laena Velaryon","\u83B1\u5A1C\xB7\u74E6\u5217\u5229\u5B89",{father:"corlys-velaryon",note:e("Dragonrider of Vhagar; wed Prince Daemon.","\u5DE8\u9F99\u74E6\u683C\u54C8\u5C14\u7684\u9A91\u624B\uFF0C\u5AC1\u7ED9\u6234\u8499\u738B\u5B50\u3002")}),a("monford-velaryon","Monford Velaryon","\u8499\u798F\u5FB7\xB7\u74E6\u5217\u5229\u5B89",{note:e("Lord of the Tides under Robert; sided with Stannis.","\u52B3\u52C3\u5728\u4F4D\u65F6\u7684\u6F6E\u6C50\u4E4B\u4E3B\uFF0C\u6295\u6548\u53F2\u5766\u5C3C\u65AF\u3002"),fate:e("Dies at the Battle of the Blackwater.","\u6B7B\u4E8E\u9ED1\u6C34\u6CB3\u4E4B\u5F79\u3002")}),a("monterys-velaryon","Monterys Velaryon","\u8499\u7279\u91CC\u65AF\xB7\u74E6\u5217\u5229\u5B89",{father:"monford-velaryon",note:e("Boy Lord of the Tides after his father.","\u7EE7\u627F\u7236\u4F4D\u7684\u5C11\u5E74\u6F6E\u6C50\u4E4B\u4E3B\u3002")}),a("aurane-waters","Aurane Waters","\u5965\u4F26\xB7\u6CB3\u6587",{note:e('"The Bastard of Driftmark"; made master of ships by Cersei.',"\u201C\u6F6E\u5934\u5C9B\u7684\u79C1\u751F\u5B50\u201D\uFF0C\u88AB\u745F\u66E6\u4EFB\u547D\u4E3A\u6D77\u519B\u5927\u81E3\u3002"),fate:e("Sails off with the new royal fleet when Cersei falls (A Feast for Crows).","\u745F\u66E6\u5931\u52BF\u65F6\u7387\u65B0\u5EFA\u7684\u738B\u5BB6\u8230\u961F\u626C\u5E06\u800C\u53BB\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\u3002")})]},{id:"celtigar",names:e("House Celtigar","\u8D5B\u63D0\u52A0\u5BB6\u65CF"),region:"crownlands",seat:"claw-isle",tier:"major",liege:null,sigil:e("Red crabs on a white field","\u767D\u5E95\u4E0A\u6563\u5E03\u7EA2\u87F9"),colors:["#f0ece2","#b5302a"],summary:e("A house of Valyrian descent on Claw Isle, sworn to Dragonstone. Lord Ardrian Celtigar, an old man fond of his treasures, joins Stannis but is captured at the Blackwater and then bends the knee to King Joffrey.","\u4E00\u4E2A\u6709\u74E6\u96F7\u5229\u4E9A\u8840\u7EDF\u7684\u5BB6\u65CF\uFF0C\u5C45\u4E8E\u722A\u5C9B\uFF0C\u6548\u5FE0\u9F99\u77F3\u5C9B\u3002\u5E74\u8FC8\u800C\u73CD\u7231\u8D22\u5B9D\u7684\u963F\u5FB7\u91CC\u5B89\xB7\u8D5B\u63D0\u52A0\u4F2F\u7235\u6295\u5954\u53F2\u5766\u5C3C\u65AF\uFF0C\u5374\u5728\u9ED1\u6C34\u6CB3\u4E4B\u5F79\u88AB\u4FD8\uFF0C\u968F\u540E\u5411\u4E54\u4F5B\u91CC\u56FD\u738B\u5C48\u819D\u3002"),refs:["acok","asos","twoiaf"]},{id:"bar-emmon",names:e("House Bar Emmon","\u5DF4\u5C14\xB7\u827E\u8499\u5BB6\u65CF"),region:"crownlands",seat:"sharp-point",tier:"minor",liege:null,sigil:e("A blue swordfish leaping on silver fretwork (per TWOIAF-era heraldry)","\u94F6\u8272\u7F51\u683C\u7EB9\u4E0A\u4E00\u6761\u8DC3\u8D77\u7684\u84DD\u8272\u5251\u9C7C\uFF08\u636E\u540E\u51FA\u7EB9\u7AE0\u8D44\u6599\uFF09"),colors:["#d8dadc","#2c5aa0"],summary:e("Lords of Sharp Point on Massey's Hook and bannermen of Dragonstone. Their lord in the books, Duram Bar Emmon, is a heavy youth of fifteen who follows Stannis to war.","\u6885\u897F\u94A9\u4E0A\u9510\u89D2\u57CE\u7684\u9886\u4E3B\uFF0C\u9F99\u77F3\u5C9B\u7684\u5C01\u81E3\u3002\u5C0F\u8BF4\u4E2D\u7684\u5BB6\u4E3B\u675C\u62C9\u59C6\xB7\u5DF4\u5C14\xB7\u827E\u8499\u662F\u4E2A\u5341\u4E94\u5C81\u7684\u80D6\u5C11\u5E74\uFF0C\u8FFD\u968F\u53F2\u5766\u5C3C\u65AF\u51FA\u5F81\u3002"),refs:["acok","twoiaf"]},{id:"massey",names:e("House Massey","\u6885\u897F\u5BB6\u65CF"),region:"crownlands",seat:"stonedance",tier:"minor",liege:null,sigil:e("A triple spiral of red, green and blue on white (semi-canon)","\u767D\u5E95\u4E0A\u7EA2\u3001\u7EFF\u3001\u84DD\u4E09\u8272\u4E09\u91CD\u87BA\u65CB\uFF08\u975E\u6B63\u5178\u7EB9\u7AE0\u8D44\u6599\uFF09"),colors:["#f2efe6","#3d6e9e"],summary:e("An ancient house of Stonedance on the hook that bears its name, sworn to Dragonstone. Ser Justin Massey is one of Stannis's knights; in A Dance with Dragons he goes to the Wall and is later sent abroad to raise sellswords.","\u77F3\u821E\u57CE\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u6240\u5728\u7684\u534A\u5C9B\u5373\u4EE5\u5176\u59D3\u547D\u540D\uFF0C\u6548\u5FE0\u9F99\u77F3\u5C9B\u3002\u8D3E\u65AF\u4E01\xB7\u6885\u897F\u7235\u58EB\u662F\u53F2\u5766\u5C3C\u65AF\u9EBE\u4E0B\u7684\u9A91\u58EB\uFF1B\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u4ED6\u6765\u5230\u957F\u57CE\uFF0C\u540E\u88AB\u6D3E\u5F80\u6D77\u5916\u62DB\u52DF\u4F63\u5175\u3002"),refs:["acok","adwd","twoiaf"]},{id:"sunglass",names:e("House Sunglass","\u6851\u683C\u62C9\u65AF\u5BB6\u65CF"),region:"crownlands",seat:"sweetport-sound",tier:"minor",liege:null,sigil:e("Seven golden seven-pointed stars in a ring on white (semi-canon)","\u767D\u5E95\u4E0A\u73AF\u5217\u4E03\u9897\u91D1\u8272\u4E03\u8292\u661F\uFF08\u975E\u6B63\u5178\u7EB9\u7AE0\u8D44\u6599\uFF09"),colors:["#f4f1e8","#c9a227"],summary:e("Lords of Sweetport Sound, sworn to Dragonstone. Lord Guncer Sunglass, a pious man of the Seven, objects when Stannis's queen's men burn the Seven's idols and is imprisoned for it.","\u751C\u6E2F\u6E7E\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u9F99\u77F3\u5C9B\u3002\u5188\u745F\xB7\u6851\u683C\u62C9\u65AF\u4F2F\u7235\u662F\u8654\u8BDA\u7684\u4E03\u795E\u4FE1\u5F92\uFF0C\u56E0\u53CD\u5BF9\u738B\u540E\u7684\u4EBA\u711A\u70E7\u4E03\u795E\u795E\u50CF\u800C\u88AB\u53F2\u5766\u5C3C\u65AF\u56DA\u7981\u3002"),refs:["acok","asos","twoiaf"]},{id:"staunton",names:e("House Staunton","\u65AF\u5766\u987F\u5BB6\u65CF"),region:"crownlands",seat:"rooks-rest",tier:"minor",liege:null,sigil:e("Not described in the novels; later heraldry gives black wings on a white band over a chequy field","\u5C0F\u8BF4\u672A\u63CF\u8FF0\uFF1B\u540E\u51FA\u7EB9\u7AE0\u8D44\u6599\u4F5C\u68CB\u76D8\u683C\u5E95\u4E0A\u767D\u8272\u6A2A\u5E26\uFF0C\u5E26\u4E0A\u4E00\u5BF9\u9ED1\u7FFC"),colors:["#6e6e6e","#141414"],summary:e("Lords of Rook's Rest on the shore of Blackwater Bay. During the Dance of the Dragons Lord Staunton declared for Rhaenyra, and the attack on his castle drew Princess Rhaenys and her dragon to their deaths.","\u9ED1\u6C34\u6E7E\u7554\u9E26\u6816\u5821\u7684\u9886\u4E3B\u3002\u201C\u8840\u9F99\u72C2\u821E\u201D\u4E2D\uFF0C\u65AF\u5766\u987F\u4F2F\u7235\u652F\u6301\u96F7\u59AE\u62C9\uFF1B\u5176\u57CE\u5821\u906D\u56F4\u653B\uFF0C\u5F15\u6765\u96F7\u59AE\u4E1D\u516C\u4E3B\u4E0E\u5979\u7684\u5DE8\u9F99\uFF0C\u4E8C\u8005\u53CC\u53CC\u846C\u8EAB\u4E8E\u6B64\u3002"),refs:["twoiaf"]},{id:"rosby",names:e("House Rosby","\u7F57\u65AF\u6BD4\u5BB6\u65CF"),region:"crownlands",seat:"rosby",tier:"minor",liege:null,sigil:e("Three red chevrons on ermine","\u767D\u8C82\u76AE\u7EB9\u5E95\u4E0A\u4E09\u9053\u7EA2\u8272\u5C71\u5F62\u7EB9"),colors:["#f5f2ea","#b32a2a"],summary:e("Lords of Rosby, close neighbours of the capital. Lord Gyles Rosby, wracked by a cough, serves on the small council under Joffrey and Tommen.","\u7F57\u65AF\u6BD4\u57CE\u7684\u9886\u4E3B\uFF0C\u7D27\u90BB\u9996\u90FD\u3002\u76D6\u5C14\u65AF\xB7\u7F57\u65AF\u6BD4\u4F2F\u7235\u54B3\u55FD\u7F20\u8EAB\uFF0C\u5728\u4E54\u4F5B\u91CC\u548C\u6258\u66FC\u4E24\u671D\u7684\u5FA1\u524D\u4F1A\u8BAE\u4EFB\u804C\u3002"),refs:["acok","affc"],members:[a("bethany-rosby","Bethany Rosby","\u8D1D\u73CA\u59AE\xB7\u7F57\u65AF\u6BD4",{note:e("Sixth wife of Lord Walder Frey.","\u74E6\u5FB7\xB7\u4F5B\u96F7\u4FAF\u7235\u7684\u7B2C\u516D\u4EFB\u59BB\u5B50\u3002")})]},{id:"stokeworth",names:e("House Stokeworth","\u53F2\u94CE\u514B\u6E25\u65AF\u5BB6\u65CF"),region:"crownlands",seat:"stokeworth",tier:"minor",liege:null,sigil:e("A white lamb holding a golden goblet, on green","\u7EFF\u5E95\u4E0A\u4E00\u53EA\u8854\u7740\u91D1\u676F\u7684\u767D\u7F8A\u7F94"),colors:["#3f7a3a","#f2efe6"],summary:e("Lords of Stokeworth, a castle north of King's Landing, and fixtures of the court. The widowed Lady Tanda schemes to find husbands for her daughters Falyse and the simple-minded Lollys.","\u53F2\u94CE\u514B\u6E25\u65AF\u57CE\u7684\u9886\u4E3B\uFF0C\u5BAB\u5EF7\u91CC\u7684\u5E38\u5BA2\u3002\u5B88\u5BE1\u7684\u5766\u59B2\u592B\u4EBA\u4E00\u5FC3\u4E3A\u4E24\u4E2A\u5973\u513F\u2014\u2014\u6CD5\u8389\u4E1D\u4E0E\u5FC3\u667A\u8FDF\u949D\u7684\u7F57\u8389\u4E1D\u2014\u2014\u7269\u8272\u592B\u5A7F\u3002"),refs:["acok","asos","affc"],members:[a("tanda-stokeworth","Tanda Stokeworth","\u5766\u59B2\xB7\u53F2\u94CE\u514B\u6E25\u65AF",{note:e("Widowed Lady of Stokeworth.","\u5B88\u5BE1\u7684\u53F2\u94CE\u514B\u6E25\u65AF\u592B\u4EBA\u3002"),fate:e("Dies after a fall from her horse (A Feast for Crows).","\u5760\u9A6C\u540E\u8EAB\u4EA1\uFF08\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\u3002")}),a("falyse-stokeworth","Falyse Stokeworth","\u6CD5\u8389\u4E1D\xB7\u53F2\u94CE\u514B\u6E25\u65AF",{mother:"tanda-stokeworth",note:e("Elder daughter; wife of Ser Balman Byrch.","\u957F\u5973\uFF0C\u5DF4\u5C14\u66FC\xB7\u62DC\u5C14\u5947\u7235\u58EB\u4E4B\u59BB\u3002"),fate:e("Handed to Qyburn for his experiments by Cersei; Ser Balman is killed.","\u88AB\u745F\u66E6\u4EA4\u7ED9\u79D1\u672C\u505A\u5B9E\u9A8C\uFF1B\u5DF4\u5C14\u66FC\u7235\u58EB\u9047\u5BB3\u3002")}),a("lollys-stokeworth","Lollys Stokeworth","\u7F57\u8389\u4E1D\xB7\u53F2\u94CE\u514B\u6E25\u65AF",{mother:"tanda-stokeworth",note:e("Younger daughter; married to the sellsword Bronn.","\u5E7C\u5973\uFF0C\u5AC1\u7ED9\u4F63\u5175\u6CE2\u9686\u3002")}),a("tyrion-tanner","Tyrion Tanner","\u63D0\u5229\u6602\xB7\u5766\u7EB3",{mother:"lollys-stokeworth",note:e("Lollys's son, named after Tyrion Lannister.","\u7F57\u8389\u4E1D\u4E4B\u5B50\uFF0C\u4EE5\u63D0\u5229\u6602\xB7\u5170\u5C3C\u65AF\u7279\u4E4B\u540D\u547D\u540D\u3002")})]},{id:"hayford",names:e("House Hayford","\u6D77\u798F\u7279\u5BB6\u65CF"),region:"crownlands",seat:"hayford",tier:"minor",liege:null,sigil:e("Green fretty over gold, a green pale wavy","\u91D1\u5E95\u7EFF\u8272\u7F51\u683C\u7EB9\uFF0C\u4E2D\u95F4\u4E00\u9053\u7EFF\u8272\u6CE2\u7EB9\u7AD6\u5E26"),colors:["#d4af37","#2f6b34"],summary:e("Lords of Hayford, a day's ride from the capital. The last of the line is the infant Lady Ermesande, wed to Tyrek Lannister for her lands; her castellan rules in her name.","\u6D77\u798F\u7279\u57CE\u7684\u9886\u4E3B\uFF0C\u8DDD\u9996\u90FD\u4E00\u65E5\u8DEF\u7A0B\u3002\u5BB6\u65CF\u672B\u88D4\u662F\u8941\u8913\u4E2D\u7684\u827E\u6885\u6563\u5FB7\u5973\u58EB\uFF0C\u4E3A\u4E86\u5979\u7684\u9886\u5730\u800C\u88AB\u8BB8\u914D\u7ED9\u6CF0\u745E\u514B\xB7\u5170\u5C3C\u65AF\u7279\uFF1B\u7531\u4EE3\u7406\u57CE\u4E3B\u4EE5\u5979\u7684\u540D\u4E49\u6CBB\u7406\u3002"),refs:["acok","affc"]},{id:"hogg",names:e("House Hogg","\u970D\u683C\u5BB6\u65CF"),region:"crownlands",seat:"sows-horn",tier:"minor",liege:"hayford",sigil:e("Not described in the novels","\u5C0F\u8BF4\u4E2D\u672A\u6709\u63CF\u8FF0"),colors:["#c98a8a","#5a3a2a"],summary:e("Landed knights of Sow's Horn, sworn to House Hayford. Ser Harys Hogg, known as Harry the Ham, wears a pig's-head helm.","\u6BCD\u732A\u89D2\u7684\u6709\u5730\u9A91\u58EB\uFF0C\u6548\u5FE0\u6D77\u798F\u7279\u5BB6\u65CF\u3002\u54C8\u91CC\u65AF\xB7\u970D\u683C\u7235\u58EB\u5916\u53F7\u201C\u706B\u817F\u54C8\u5229\u201D\uFF0C\u6234\u7740\u4E00\u9876\u732A\u5934\u76D4\u3002"),refs:["awoiaf"]},{id:"buckwell",names:e("House Buckwell","\u5DF4\u514B\u5A01\u5C14\u5BB6\u65CF"),region:"crownlands",seat:"the-antlers",tier:"minor",liege:null,sigil:e("Golden antlers on vair (semi-canon)","\u677E\u9F20\u76AE\u7EB9\u5E95\u4E0A\u4E00\u5BF9\u91D1\u8272\u9E7F\u89D2\uFF08\u975E\u6B63\u5178\u7EB9\u7AE0\u8D44\u6599\uFF09"),colors:["#7f9bb8","#d4af37"],summary:e("Lords of the Antlers, a lordship north of King's Landing. Lord Buckwell is among the crownlands lords at court; the house plays a small part in the books.","\u9E7F\u89D2\u5821\u7684\u9886\u4E3B\uFF0C\u5C01\u5730\u5728\u541B\u4E34\u4EE5\u5317\u3002\u5DF4\u514B\u5A01\u5C14\u4F2F\u7235\u662F\u51FA\u5165\u5BAB\u5EF7\u7684\u738B\u9886\u8D35\u65CF\u4E4B\u4E00\uFF0C\u5BB6\u65CF\u5728\u5C0F\u8BF4\u4E2D\u620F\u4EFD\u4E0D\u591A\u3002"),refs:["asos","twoiaf"]},{id:"rykker",names:e("House Rykker","\u96F7\u514B\u5BB6\u65CF"),region:"crownlands",seat:"dun-fort",tier:"minor",liege:null,sigil:e("Two black warhammers crossed on a white saltire, on blue","\u84DD\u5E95\u767D\u8272\u659C\u5341\u5B57\u4E0A\u4EA4\u53C9\u7684\u4E24\u67C4\u9ED1\u8272\u6218\u9524"),colors:["#2e4f8a","#141414"],summary:e("Lords of Duskendale since the fall of the Darklyns. Lord Rykker leads his men to King's Landing during the war, leaving the Dun Fort to a castellan.","\u8FBE\u514B\u6797\u5BB6\u65CF\u8986\u706D\u540E\u6210\u4E3A\u66AE\u8C37\u9547\u7684\u9886\u4E3B\u3002\u6218\u4E89\u671F\u95F4\u96F7\u514B\u4F2F\u7235\u7387\u90E8\u524D\u5F80\u541B\u4E34\uFF0C\u628A\u6697\u5821\u7559\u7ED9\u4EE3\u7406\u57CE\u4E3B\u770B\u5B88\u3002"),refs:["affc","twoiaf"]},{id:"darklyn",names:e("House Darklyn","\u8FBE\u514B\u6797\u5BB6\u65CF"),region:"crownlands",seat:"duskendale",otherSeats:["dun-fort"],tier:"extinct",liege:null,sigil:e("Black and gold lozenges, with seven white shields on a red band","\u9ED1\u91D1\u83F1\u683C\u7EB9\u5E95\uFF0C\u7EA2\u5E26\u4E0A\u6709\u4E03\u9762\u767D\u8272\u5C0F\u76FE"),colors:["#1f1f1f","#c9a227"],summary:e("An ancient line of First Men kings and later lords of Duskendale, who gave seven knights to the Kingsguard. Lord Denys Darklyn seized Aerys II during the Defiance of Duskendale; when the king was rescued, the whole house was put to death.","\u4E00\u8109\u53E4\u8001\u7684\u5148\u6C11\u738B\u65CF\uFF0C\u540E\u4E3A\u66AE\u8C37\u9547\u9886\u4E3B\uFF0C\u66FE\u6709\u4E03\u4EBA\u4F4D\u5217\u5FA1\u6797\u94C1\u536B\u3002\u201C\u66AE\u8C37\u9547\u4E4B\u53D8\u201D\u4E2D\uFF0C\u4E39\u5C3C\u65AF\xB7\u8FBE\u514B\u6797\u4F2F\u7235\u6263\u62BC\u4E86\u4F0A\u91CC\u65AF\u4E8C\u4E16\uFF1B\u56FD\u738B\u83B7\u6551\u540E\uFF0C\u5168\u65CF\u88AB\u5904\u6B7B\u3002"),refs:["asos","twoiaf"]},{id:"hollard",names:e("House Hollard","\u970D\u62C9\u5FB7\u5BB6\u65CF"),region:"crownlands",tier:"minor",liege:"darklyn",sigil:e("Red and pink stripes, with three golden crowns on a blue chief","\u7EA2\u7C89\u76F8\u95F4\u6A2A\u7EB9\uFF0C\u84DD\u8272\u9876\u5E26\u4E0A\u4E09\u9876\u91D1\u51A0"),colors:["#c0394b","#e8a3b2"],summary:e("Bannermen of the Darklyns, destroyed with them after the Defiance of Duskendale. Only the boy Dontos was spared at Ser Barristan's plea; he grows into a drunken knight, later made Joffrey's fool.","\u8FBE\u514B\u6797\u5BB6\u65CF\u7684\u5C01\u81E3\uFF0C\u201C\u66AE\u8C37\u9547\u4E4B\u53D8\u201D\u540E\u4E0E\u5176\u4E00\u540C\u8986\u706D\u3002\u53EA\u6709\u5C11\u5E74\u5510\u6258\u65AF\u56E0\u5DF4\u5229\u65AF\u5766\u7235\u58EB\u6C42\u60C5\u800C\u5E78\u514D\uFF1B\u4ED6\u957F\u5927\u540E\u6210\u4E86\u4E2A\u9152\u9B3C\u9A91\u58EB\uFF0C\u540E\u6765\u88AB\u4E54\u4F5B\u91CC\u8D2C\u4E3A\u5F04\u81E3\u3002"),refs:["agot","acok","asos"]},{id:"chelsted",names:e("House Chelsted","\u5207\u65AF\u7279\u5BB6\u65CF"),region:"crownlands",tier:"minor",liege:null,sigil:e("Per bend green and white, a spiked mace and a silver dagger crossed","\u7EFF\u767D\u659C\u5206\u5E95\uFF0C\u4EA4\u53C9\u7684\u72FC\u7259\u9524\u4E0E\u94F6\u5315\u9996"),colors:["#3a7a45","#e9ecef"],summary:e("A crownlands house. Lord Qarlton Chelsted served Aerys II as Hand; when he protested the caches of wildfire hidden under the city, the king burned him alive.","\u738B\u9886\u7684\u5BB6\u65CF\u3002\u5938\u987F\xB7\u5207\u65AF\u7279\u4F2F\u7235\u66FE\u4EFB\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u9996\u76F8\uFF0C\u56E0\u53CD\u5BF9\u5728\u57CE\u4E0B\u57CB\u85CF\u91CE\u706B\u800C\u88AB\u56FD\u738B\u6D3B\u6D3B\u70E7\u6B7B\u3002"),refs:["asos","twoiaf"]},{id:"blount",names:e("House Blount","\u5E03\u52B3\u7279\u5BB6\u65CF"),region:"crownlands",tier:"minor",liege:null,sigil:e("A red bend sinister between two black porcupines, on green","\u7EFF\u5E95\uFF0C\u7EA2\u8272\u5DE6\u659C\u5E26\u4E24\u4FA7\u5404\u4E00\u53EA\u9ED1\u8272\u8C6A\u732A"),colors:["#3a6e3a","#b32a2a"],summary:e("A minor crownlands house best known for Ser Boros Blount of the Kingsguard, a heavy, cowardly knight who serves Joffrey and Cersei.","\u738B\u9886\u7684\u5C0F\u5BB6\u65CF\uFF0C\u4EE5\u5FA1\u6797\u94C1\u536B\u67CF\u6D1B\u65AF\xB7\u5E03\u52B3\u7279\u7235\u58EB\u6700\u4E3A\u4EBA\u77E5\uFF1B\u6B64\u4EBA\u8EAB\u8EAF\u7B28\u91CD\u3001\u80C6\u5C0F\u602F\u61E6\uFF0C\u5148\u540E\u4E3A\u4E54\u4F5B\u91CC\u4E0E\u745F\u66E6\u6548\u547D\u3002"),refs:["agot","acok","affc"]},{id:"brune-of-brownhollow",names:e("House Brune of Brownhollow","\u8910\u8C37\u5821\u7684\u5E03\u4F26\u5BB6\u65CF"),region:"crownlands",seat:"brownhollow",tier:"minor",liege:null,sigil:e("A brown bear's paw on white within a double brown border (semi-canon)","\u767D\u5E95\u4E0A\u4E00\u53EA\u8910\u8272\u718A\u638C\uFF0C\u5916\u56F4\u53CC\u91CD\u8910\u8272\u8FB9\u6846\uFF08\u975E\u6B63\u5178\u7EB9\u7AE0\u8D44\u6599\uFF09"),colors:["#f0ece2","#6b4a2b"],summary:e("One of the clannish petty houses of Crackclaw Point, sharing its name with the Brunes of the Dyre Den. Like their neighbours they long remembered their loyalty to the dragon kings.","\u87F9\u722A\u534A\u5C9B\u5B97\u65CF\u6C14\u606F\u6D53\u539A\u7684\u5C0F\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u4E0E\u51F6\u7A74\u5821\u7684\u5E03\u4F26\u5BB6\u65CF\u540C\u59D3\u3002\u4E0E\u90BB\u5C45\u4EEC\u4E00\u6837\uFF0C\u4ED6\u4EEC\u957F\u4E45\u94ED\u8BB0\u5BF9\u9F99\u738B\u7684\u5FE0\u8BDA\u3002"),refs:["acok","twoiaf"]},{id:"brune-of-the-dyre-den",names:e("House Brune of the Dyre Den","\u51F6\u7A74\u5821\u7684\u5E03\u4F26\u5BB6\u65CF"),region:"crownlands",seat:"dyre-den",tier:"minor",liege:null,sigil:e("Not described in the novels","\u5C0F\u8BF4\u4E2D\u672A\u6709\u63CF\u8FF0"),colors:["#6b4a2b","#d9c9a6"],summary:e("The other Brune house of Crackclaw Point. Their lord is among those who must choose between Stannis and the Iron Throne after the Blackwater.","\u87F9\u722A\u534A\u5C9B\u7684\u53E6\u4E00\u652F\u5E03\u4F26\u5BB6\u65CF\u3002\u9ED1\u6C34\u6CB3\u4E4B\u5F79\u540E\uFF0C\u5176\u5BB6\u4E3B\u4E5F\u662F\u4E0D\u5F97\u4E0D\u5728\u53F2\u5766\u5C3C\u65AF\u4E0E\u94C1\u738B\u5EA7\u4E4B\u95F4\u4F5C\u51FA\u6289\u62E9\u7684\u9886\u4E3B\u4E4B\u4E00\u3002"),refs:["acok","affc","twoiaf"]},{id:"boggs",names:e("House Boggs","\u535A\u683C\u65AF\u5BB6\u65CF"),region:"crownlands",tier:"minor",liege:null,sigil:e("Not described in the novels","\u5C0F\u8BF4\u4E2D\u672A\u6709\u63CF\u8FF0"),colors:["#5c6b4a","#c2b48a"],summary:e("A petty house of Crackclaw Point, counted among the peninsula's stubborn, inward-looking lords who rallied to Stannis in the war.","\u87F9\u722A\u534A\u5C9B\u7684\u5C0F\u5BB6\u65CF\uFF0C\u5C5E\u4E8E\u534A\u5C9B\u4E0A\u56FA\u6267\u800C\u6392\u5916\u3001\u5728\u6218\u4E89\u4E2D\u6295\u5954\u53F2\u5766\u5C3C\u65AF\u7684\u9886\u4E3B\u4E4B\u5217\u3002"),refs:["acok","twoiaf"]},{id:"crabb",names:e("House Crabb","\u514B\u83B1\u52C3\u5BB6\u65CF"),region:"crownlands",seat:"the-whispers",tier:"minor",liege:null,sigil:e("Not described in the novels","\u5C0F\u8BF4\u4E2D\u672A\u6709\u63CF\u8FF0"),colors:["#a5402d","#e6dcc8"],summary:e("An old Crackclaw Point house that once held the Whispers, now a ruin. Its pride is the legend of Ser Clarence Crabb, a giant knight said to have carried home the heads of the men he slew \u2014 a tale retold by Nimble Dick in A Feast for Crows.","\u87F9\u722A\u534A\u5C9B\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u66FE\u9886\u6709\u5982\u4ECA\u5DF2\u6210\u5E9F\u589F\u7684\u4F4E\u8BED\u5821\u3002\u5BB6\u65CF\u5F15\u4EE5\u4E3A\u50B2\u7684\u662F\u514B\u62C9\u4F26\u65AF\xB7\u514B\u83B1\u52C3\u7235\u58EB\u7684\u4F20\u8BF4\uFF1A\u636E\u8BF4\u8FD9\u4F4D\u5DE8\u4EBA\u822C\u7684\u9A91\u58EB\u4F1A\u628A\u4ED6\u65A9\u6740\u4E4B\u4EBA\u7684\u9996\u7EA7\u5E26\u56DE\u5BB6\u2014\u2014\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u7075\u5DE7\u7684\u8FEA\u514B\u8BB2\u8FF0\u4E86\u8FD9\u4E2A\u6545\u4E8B\u3002"),refs:["affc","twoiaf"]}]};export{t as default};
